/**
 * Documentation generated by Claude
 * Purpose: Rules and arithmetic for campsite ratings, including removing one.
 * Role / Design Pattern: Pure policy object, kept free of Firebase so it can be unit tested.
 * Outstanding Issues: None.
 */
package com.example.campsitelottery

import java.util.Locale

/**
 * Validation and running-total math for campsite ratings.
 *
 * Each user has at most one rating per campsite. The campsite document keeps the
 * running [Totals] so screens can show the average without reading every rating.
 */
object RatingPolicy {

    const val MIN_STARS = 1
    const val MAX_STARS = 5

    /**
     * Running totals stored on a campsite.
     *
     * @property sum Sum of all star values.
     * @property count Number of users who have rated.
     */
    data class Totals(val sum: Long = 0, val count: Int = 0) {
        /** Average stars, or 0.0 when nobody has rated yet. */
        val average: Double get() = if (count <= 0) 0.0 else sum.toDouble() / count
    }

    /** Returns true if [stars] is a whole number from [MIN_STARS] to [MAX_STARS]. */
    fun isValid(stars: Int): Boolean = stars in MIN_STARS..MAX_STARS

    /** @throws IllegalArgumentException if [stars] is out of range. */
    fun requireValid(stars: Int) {
        require(isValid(stars)) { "A rating must be between $MIN_STARS and $MAX_STARS stars." }
    }

    /** Anyone except the campsite's owner may rate it. */
    fun canRate(ownerId: String, userId: String): Boolean =
        userId.isNotBlank() && ownerId != userId

    /**
     * Applies one user's rating to the campsite's totals.
     *
     * @param totals the campsite's current totals.
     * @param previousStars this user's earlier rating, or null if this is their first.
     * @param newStars the rating being submitted.
     * @return the updated totals. A changed rating adjusts the sum but not the count.
     */
    fun apply(totals: Totals, previousStars: Int?, newStars: Int): Totals {
        requireValid(newStars)
        return if (previousStars == null || totals.count <= 0) {
            Totals(totals.sum + newStars, totals.count + 1)
        } else {
            Totals(totals.sum - previousStars + newStars, totals.count)
        }
    }

    /**
     * Takes one rating back out of the campsite's totals.
     *
     * @param totals the campsite's current totals.
     * @param removedStars the stars of the rating being removed.
     * @return the updated totals, never below zero.
     */
    fun remove(totals: Totals, removedStars: Int): Totals =
        if (totals.count <= 1) Totals()
        else Totals((totals.sum - removedStars).coerceAtLeast(0), totals.count - 1)

    /** Error shown when a rating changed between an admin seeing it and removing it. */
    const val CHANGED_MESSAGE = "This rating was changed. Check it again before removing it."

    /** Stars as text, e.g. "★★☆☆☆", or "Invalid rating (7)" if [stars] is out of range. */
    fun starText(stars: Int): String =
        if (isValid(stars)) "★".repeat(stars) + "☆".repeat(MAX_STARS - stars)
        else "Invalid rating ($stars)"

    /** Ratings sorted newest first; ones with no date go last. */
    fun sortNewestFirst(ratings: List<CampsiteRating>): List<CampsiteRating> =
        ratings.sortedByDescending { it.updatedAt?.time ?: Long.MIN_VALUE }

    /** Text shown on the campsite screen, e.g. "4.3 ★ (12 ratings)". */
    fun summary(totals: Totals): String = when (totals.count) {
        0 -> "No ratings yet"
        1 -> String.format(Locale.US, "%.1f ★ (1 rating)", totals.average)
        else -> String.format(Locale.US, "%.1f ★ (%d ratings)", totals.average, totals.count)
    }

    /** Totals stored on [campsite]. */
    fun totalsOf(campsite: Campsite): Totals = Totals(campsite.ratingSum, campsite.ratingCount)
}
